const ORDER = "(ord-\\d{4})";

const REFUND = "(rfd-\\d{4})";

const REFUSALS = { NOT_FOUND: 404, FORBIDDEN: 403, CONFLICT: 409, INVALID: 400 };

const refundAnswered = (r, ok = 200) => (r?.error ? { status: REFUSALS[r.error], body: { error: r.error } } : { status: ok, body: r });
